utf8::encode($s);
exec("/workspace/dataset/test8_executable","--payload",$s,"--secret","s") or die "exec failed";
PEOF
cd /tmp && perl /tmp/gen.pl 'join("",map{chr($_)} 0x80..0xFF)' > /tmp/o.txt 2>/tmp/e.txt; echo EXIT=$?; sed -n 2p /tmp/o.txt; echo "---STDERR---"; cat /tmp/e.txt

